formula:
halfHour:=PERIOD=30; supported:=halfHour OR PERIOD=1440; ready:=BARSCOUNT(CLOSE)>80;
e5:=EMA(CLOSE,5); e21:=EMA(CLOSE,21); e55:=EMA(CLOSE,55);
raw:=IF(halfHour,100*(CLOSE-LLV(LOW,27))/MAX(HHV(HIGH,27)-LLV(LOW,27),0.0001),100*(CLOSE-LLV(LOW,20))/MAX(HHV(HIGH,20)-LLV(LOW,20),0.0001));
k:=SMA(raw,5,1); d:=SMA(k,3,1); dp:3*k-2*d,COLORMAGENTA,LINETHICK2; dpMean:=EMA(dp,4);
pos:=100*(CLOSE-LLV(LOW,55))/MAX(HHV(HIGH,55)-LLV(LOW,55),0.0001); lowPos:100-pos,COLORGREEN,LINETHICK2;
tr:=MAX(HIGH-LOW,MAX(ABS(HIGH-REF(CLOSE,1)),ABS(LOW-REF(CLOSE,1)))); atr:=MA(tr,14);
volumeBase:=IF(halfHour,(REF(VOL,8)+REF(VOL,16)+REF(VOL,24)+REF(VOL,32)+REF(VOL,40))/5,REF(MA(VOL,20),1)); rv:=VOL/MAX(volumeBase,1);
signedVolume:=IF(ISVALID(REF(CLOSE,1)),IF(CLOSE=REF(CLOSE,1),0,SIGN(CLOSE-REF(CLOSE,1))*VOL),DRAWNULL); obv5:=SUM(signedVolume,5);
volumeGood:=rv>=IF(halfHour,1.05,1.10) AND obv5>0;
bottomCount:=IF(ISVALID(pos) AND ISVALID(dp) AND ISVALID(atr),(pos<=20)+(dp<=25)+(CLOSE<e21-atr),DRAWNULL);
topCount:=IF(ISVALID(bottomCount),(pos>=80)+(dp>=75)+(CLOSE>e21+1.4*atr),DRAWNULL);
bottomRaw:=bottomCount>=2; topRaw:=topCount>=2;
bottomSignal:=supported AND ready AND IF(halfHour,FILTER(bottomRaw AND NOT REF(bottomRaw,1),6),FILTER(bottomRaw AND NOT REF(bottomRaw,1),5));
higherLow:=LLV(LOW,3)>REF(LLV(LOW,5),3); momentum:=CROSS(dp,18); volumeSupport:=rv>=0.9 OR obv5>0;
tryPre:=BARSLAST(bottomRaw)<20 AND momentum AND higherLow AND volumeSupport AND CLOSE>OPEN AND CLOSE>REF(CLOSE,1) AND CLOSE>e5 AND CLOSE<e21+1.2*atr;
trySignal:=supported AND ready AND IF(halfHour,FILTER(tryPre,10),FILTER(tryPre,7)); tryAge:=BARSLAST(trySignal);
breakHigh:=IF(halfHour,REF(HHV(HIGH,8),1),REF(HHV(HIGH,6),1));
addPre:=tryAge<30 AND tryAge>=4 AND CLOSE>breakHigh AND CLOSE>e21 AND e21>REF(e21,1) AND higherLow AND dp>=40 AND dp<=85 AND volumeGood AND CLOSE<e21+2*atr;
addSignal:=supported AND ready AND IF(halfHour,FILTER(addPre,20),FILTER(addPre,15));
topSignal:=supported AND ready AND IF(halfHour,FILTER(topRaw AND NOT REF(topRaw,1),8),FILTER(topRaw AND NOT REF(topRaw,1),6));
baseStop:=REF(LLV(LOW,8),1)-0.15*atr; stop:=IF(halfHour,HHV(baseStop,12),HHV(baseStop,10));
breakdown:=CLOSE<stop; exitRaw:=breakdown AND REF(breakdown,1) AND CLOSE<e21 AND dp<50;
exitSignal:=supported AND ready AND IF(halfHour,FILTER(exitRaw AND NOT REF(exitRaw,1),10),FILTER(exitRaw AND NOT REF(exitRaw,1),8));
lowerHigh:=HHV(HIGH,3)<REF(HHV(HIGH,5),3);
reduceRaw:=BARSLAST(topRaw)<IF(halfHour,16,12) AND lowerHigh AND dp<dpMean AND CLOSE<e5 AND CLOSE<REF(CLOSE,1) AND NOT exitSignal;
reduceSignal:=supported AND ready AND IF(halfHour,FILTER(reduceRaw AND NOT REF(reduceRaw,1),12),FILTER(reduceRaw AND NOT REF(reduceRaw,1),8));
HLINE(80),COLORGRAY,DOTLINE; HLINE(50),COLORGRAY,DOTLINE; HLINE(20),COLORGRAY,DOTLINE;
STICKLINE(bottomSignal,0,12,2,0),COLORCYAN; DRAWTEXT(bottomSignal,14,'底观',1),COLORCYAN;
STICKLINE(trySignal,0,30,3,0),COLORRED; DRAWTEXT(trySignal,32,'试仓',1),COLORRED;
STICKLINE(addSignal,0,50,3,0),COLORMAGENTA; DRAWTEXT(addSignal,52,'加仓',1),COLORMAGENTA;
STICKLINE(topSignal,88,100,1,0),COLORYELLOW; DRAWTEXT(topSignal,84,'高观',1),COLORYELLOW;
STICKLINE(reduceSignal,70,100,3,0),COLORGREEN; DRAWTEXT(reduceSignal,66,'减仓',1),COLORGREEN;
STICKLINE(exitSignal,0,100,1,0),COLORWHITE; DRAWTEXT(exitSignal,91,'退出',1),COLORWHITE;
TOOLTIP(dp,'多方强度',2,''),COLORMAGENTA;
TOOLTIP(lowPos,'低位程度',2,''),COLORGREEN;
TOOLTIP(rv,'相对量能',2,'x'),COLORGRAY;
TOOLTIP(stop,'动态防守价',3,''),COLORWHITE;
TOOLTIP(e21,'趋势参考价',3,''),COLORWHITE;
